function rangeBitwiseAnd(left: number, right: number): number {
  // Ответ — общий двоичный префикс left и right, дополненный нулями.
  // Сдвигаем оба числа вправо, пока они не совпадут
  let shift = 0;
  while (left < right) {
    left >>= 1;
    right >>= 1;
    shift++;
  }

  // Возвращаем общий префикс на место; младшие shift битов — нули
  return left << shift;
}

// Время: O(log right) — не больше 31 итерации
// Память: O(1)
